// Canonical pure group rules. Browser asset is generated byte-for-byte from here.
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.LieHcpRules=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
    'use strict';
    function requireValue(ok,message){if(!ok)throw new Error(message);}
    function number(value){requireValue(typeof value==='number'&&Number.isFinite(value),'Invalid numeric value');return value;}
    function normalizeHcp(value){number(value);requireValue(value>=0&&value<=54,'HCP outside 0..54');return Math.floor((value+Number.EPSILON)*10+0.5)/10;}
    function normalizeRound(round){
        requireValue(round&&['9','9-Front','9-Back','18'].includes(round.rundenTyp),'Invalid round type');
        const type=round.rundenTyp==='9'?'9-Front':round.rundenTyp,H=type==='18'?18:9;
        requireValue(round.bahnAnzahl===H,'Invalid round length');return {type,H,first:type==='9-Back'?10:1,last:type==='9-Back'?18:H};
    }
    function played(round,course){
        const r=normalizeRound(round);requireValue(Array.isArray(course),'Missing course holes');
        requireValue(course.every(h=>Number.isSafeInteger(h.nr)&&h.nr>=1&&h.nr<=18&&Number.isSafeInteger(h.par)&&h.par>0&&Number.isSafeInteger(h.si)&&h.si>0),'Invalid course hole');
        requireValue(new Set(course.map(h=>h.nr)).size===course.length,'Duplicate hole');
        const holes=course.filter(h=>h.nr>=r.first&&h.nr<=r.last).sort((a,b)=>a.nr-b.nr);
        requireValue(holes.length===r.H&&new Set(holes.map(h=>h.si)).size===r.H,'Missing hole or duplicate played SI');return holes;
    }
    function snapshot(round,course,hcp,table){
        const start=normalizeHcp(hcp),holes=played(round,course),r=normalizeRound(round);
        const matches=(table||[]).filter(row=>row.vorgabe===start);
        requireValue(matches.length<=1,'Ambiguous course handicap');
        const total18=matches.length?matches[0].spielvorgabe:Math.floor(start+0.5);
        requireValue(Number.isSafeInteger(total18)&&total18>=0,'Invalid course playing allowance');
        const total=r.H===9?Math.floor(total18/2+0.5):total18,rank=holes.slice().sort((a,b)=>a.si-b.si);
        const allowances=Object.fromEntries(rank.map((h,i)=>[h.nr,Math.floor(total/r.H)+(i<total%r.H?1:0)]));
        return {version:1,type:r.type,startHcp:start,holes:holes.map(h=>h.nr),holeData:holes.map(h=>({nr:h.nr,par:h.par,si:h.si})),holeAllowances:allowances,playingTotal:total};
    }
    function points(strokes,par,given,strich){
        requireValue(typeof strich==='boolean','Invalid Strich flag');
        requireValue(Number.isSafeInteger(par)&&par>0&&Number.isSafeInteger(given)&&given>=0,'Invalid points basis');
        if(strich)return 0;
        requireValue(Number.isSafeInteger(strokes)&&strokes>0,'Missing or invalid strokes');return Math.max(0,2+par+given-strokes);
    }
    function progress(start,netto,count){
        const h=normalizeHcp(start);requireValue(Number.isSafeInteger(netto)&&netto>=0&&[9,18].includes(count),'Invalid progression');
        const delta=netto-count*2,tenths=Math.round(h*10)+(delta>0?-5*delta:-delta);return Math.min(540,Math.max(0,tenths))/10;
    }
    function evaluate(round,course,start,cards,allowances){
        const h=normalizeHcp(start),holes=played(round,course),allowed=new Set(holes.map(x=>x.nr)),seen=new Set(),errors=[];
        requireValue(allowances&&typeof allowances==='object','Missing round allowances');
        for(const hole of holes)requireValue(Number.isSafeInteger(allowances[hole.nr])&&allowances[hole.nr]>=0,'Missing round hole allowance');
        let totalNetto=0,totalStrokes=0,playedHoles=0,hasStrich=false;
        for(const card of cards||[]){
            if(!Number.isSafeInteger(card.hole)||!allowed.has(card.hole)||seen.has(card.hole)){errors.push('duplicate-or-outside-hole');continue;}seen.add(card.hole);
            if(card.maxscore!==undefined&&typeof card.maxscore!=='boolean'){errors.push('invalid-strich');continue;}
            if(card.maxscore===true){playedHoles++;hasStrich=true;continue;}
            if(card.strokes===undefined||card.strokes===null||card.strokes==='')continue;
            if(!Number.isSafeInteger(card.strokes)||card.strokes<=0){errors.push('invalid-strokes');continue;}
            const hole=holes.find(x=>x.nr===card.hole);playedHoles++;totalStrokes+=card.strokes;totalNetto+=points(card.strokes,hole.par,allowances[card.hole],false);
        }
        const valid=!errors.length,complete=valid&&playedHoles===holes.length;
        return {startHcp:h,endHcp:complete?progress(h,totalNetto,holes.length):null,totalNetto,totalStrokes:hasStrich?null:totalStrokes,
            playedHoles,requiredHoles:holes.length,valid,complete,bruttoEligible:complete&&!hasStrich,hasStrich,errors};
    }
    function plan(rounds,cards,initial,courseFor,tableFor){
        const currentHcp=Object.fromEntries(Object.entries(initial).map(([id,value])=>[id,normalizeHcp(value)])),entries=[],blocked=new Set();
        for(const round of rounds.slice().sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.id).localeCompare(String(b.id)))){
            const players=String(round.teilnehmerCsv||'').split(',').filter(Boolean);
            const ids=players.length?players:Object.keys(initial);
            for(const id of ids){if(!Object.hasOwn(currentHcp,id))continue;
                if(blocked.has(id)){entries.push({roundId:round.id,playerId:id,complete:false,blocked:true,endHcp:null});continue;}
                const start=currentHcp[id],snap=snapshot(round,courseFor(round),start,tableFor(round));
                const raw=cards.filter(c=>c.spieltagId===round.id&&c.spielerId===id);
                const result=evaluate(round,courseFor(round),start,raw,snap.holeAllowances);
                entries.push({roundId:round.id,playerId:id,...result,holeAllowances:snap.holeAllowances});
                if(result.complete)currentHcp[id]=result.endHcp;
                else blocked.add(id);
            }
        }
        return {version:1,entries,currentHcp,blockedPlayers:[...blocked]};
    }
    function validateRoundSnapshot(round,members){
        requireValue(round?.hcpSnapshotVersion===1&&round.hcpStart&&round.holeAllowances&&Array.isArray(round.hcpHoleData),'Round start snapshots missing or unverified');
        for(const id of members){
            const expected=snapshot(round,round.hcpHoleData,round.hcpStart[id],round.hcpCourseTable||[]),given=round.holeAllowances[id];
            requireValue(round.hcpStart[id]===expected.startHcp&&given&&Object.keys(given).length===expected.holes.length
                &&expected.holes.every(h=>given[h]===expected.holeAllowances[h]),'Round snapshot inconsistent');
        }
        return true;
    }
    return Object.freeze({version:1,normalizeHcp,normalizeRound,played,snapshot,points,progress,evaluate,plan,validateRoundSnapshot});
});
